-- Portal administration and audit. Dates are UTC.
-- Run with privileges for PROSPECT. Existing tables are preserved.
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE PROSPECT.AUDITTXTPROS ("Code" NUMBER(10) NOT NULL,"Sub Code" NUMBER(10) DEFAULT 0 NOT NULL,"Message" VARCHAR2(80),"Detail Message" CLOB,"Action Name" VARCHAR2(80) NOT NULL,CONSTRAINT PK_AUDITTXTPROS PRIMARY KEY ("Code","Sub Code"),CONSTRAINT UQ_AUDITTXTPROS_ACTION UNIQUE ("Action Name"))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE PROSPECT.AUDITLOGPROS ("Log Stamp" NUMBER(18) NOT NULL,"Time Stamp" TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP),"User ID" NUMBER(10),"Program" VARCHAR2(50),"Code" NUMBER(10),"Sub Code" NUMBER(10),"Error Level" NUMBER(2),"Additional Information" CLOB,"Target Prospect Key" NUMBER(10),CONSTRAINT PK_AUDITLOGPROS PRIMARY KEY ("Log Stamp"))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE SEQUENCE PROSPECT.AUDITLOGPROS_SEQ START WITH 1 CACHE 100'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX PROSPECT.IX_AUDITLOGPROS_TIME ON PROSPECT.AUDITLOGPROS ("Time Stamp","Log Stamp")'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX PROSPECT.IX_AUDITLOGPROS_USER ON PROSPECT.AUDITLOGPROS ("User ID","Time Stamp")'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
MERGE INTO PROSPECT.AUDITTXTPROS t USING (SELECT 1 c,'LOGIN' a,'Login' m FROM dual) s ON (t."Action Name"=s.a) WHEN NOT MATCHED THEN INSERT ("Code","Sub Code","Action Name","Message","Detail Message") VALUES (s.c,0,s.a,s.m,'Portal service action; timestamps are UTC');
